      "intro": "商周人的礼，先从吃讲起。祭祀要先摆好肉和饭，宴请要先布好鼎和豆，食器是一切礼仪的基础。本章十二件器物分成两路：一路是炊器——鼎、鬲、甗、鍑、釜，直接接触火，负责煮和蒸；一路是盛食器——簋、簠、盨、豆、敦、盂、盆，负责把饭食端到神和人面前。吃什么、盛在什么器物里、摆几件，当时都有明文规定，后人说的\"钟鸣鼎食\"，指的就是这种讲排场、更讲规矩的生活。每件器物说七件事，白话讲述，古书原文集中在\"史料记载\"一栏并附解释。"
