      "intro": "商人的庙堂泡在酒里。《史记》说纣王\"以酒为池，悬肉为林\"，说法夸张，但殷墟大墓里酒器动辄成十成百是实情。周人取代商人后，第一件大事就是戒酒，《尚书·酒诰》专门告诫：聚众饮酒要送官严办。于是考古所见一目了然：商墓以觚、爵为中心，西周中期以后酒器骤减、食器当家——一个王朝的亡国教训，全部写在器物的兴衰表上。本章十三件酒器，从爵讲到缶，一头是王朝的巅峰，一头是民间的余音。古书里的相关原文，集中在每件器物的\"史料记载\"一栏，附白话解释。"
