        "总介绍": "卮是周秦汉晋间常见的饮酒器名，考古所称铜卮多为圆筒形杯体，直壁深腹，常带环形或半环形鋬耳，有的配盖。它的核心动作是执耳举杯饮酒，与大腹盛酒的壶、锺不同；与觯的名实关系又较复杂，近年研究依据器物自名认为部分卮可视作觯系统中的带柄杯形变体。",
        "形制与工艺": "典型卮以圆筒形器身为主，壁面较直，腹深，侧面安置单环鋬或半环耳，盖可有可无。青铜卮需铸成较薄而适于手持的杯体，并处理鋬耳与器身的连接；汉代还大量存在漆卮。它与爵的流、尾、柱、三足结构明显不同，也不像壶、锺那样以大容量贮盛为主要形态。",
        "用途": "卮主要用于个人饮酒和宴饮中的奉酒、祝寿等动作，容量与手持尺度决定它更接近杯类，而不是贮酒容器。故宫所引《史记》《汉书》均出现“奉卮酒”“奉玉卮”为寿的情形，说明卮可直接送至饮者手中。它与尊、壶的区别在于后者主要承装或转盛酒液，饮用还需再分酌。",
        "使用方式": "使用卮时可握持鋬耳或杯身，斟入酒后直接奉饮；有盖者可在未饮时覆合。文献中的“奉卮酒为寿”说明它适合在席间完成斟酒、奉献、举饮这一连续动作。它没有爵常见的流、尾、柱、三足结构，也不像尊、锺等大容量盛器那样以贮酒为主要任务，器形更接近个人杯具。",
        "礼仪与制度": "卮可进入宴飨、祝寿和高等级饮宴，但现有材料不足以支持把某种铜卮件数直接对应某一爵位。器名在先秦至汉代发生变化，宋以来又有不同定名，因此礼仪说明应以具体墓葬、铭文或文献场景为准。可确认的是，卮在文献中承担奉酒、为寿的饮器角色，而非固定的国家礼制等级标志。",
        "史料记载": "《史记·项羽本纪》有“沛公奉卮酒为寿”，《汉书·高帝纪下》有“上奉玉卮为太上皇寿”，两处都把卮放在祝寿、奉酒的具体动作中。另有出土铜卮保存器物自名，可确认“卮”并非完全由后世按外形追定。现有这些文献和自名足以说明器名与饮用场景，但不能据此规定铜卮的固定件数或身份等级。",
        "器物组合": "卮在宴饮系统中可与贮酒、分酒器配合：酒先置于壶、锺、尊等较大容器，再斟入卮供个人饮用；汉墓中还可见卮与耳杯、盘、锺、钫等处在同一饮食器用系统。卮与觯的器名边界不能简单按外形切开，因此它可说明杯形饮器之间的亲缘关系，却不能据此设定固定套数。"
