        "总介绍": "钫是盛行于战国末至西汉初的方形壶类容器，器名在汉代材料中较明确。典型形制为方口或近方口、长颈、大腹、带盖，腹侧常有铺首衔环；自铭材料说明它可装酒浆，也可作为有容量标识的盛器。它与圆体壶的主要区别在器身平面呈方形，与饮酒用卮则在容量和取用方式上不同。",
        "形制与工艺": "青铜钫通常采用方形或四面弧收的器体，口、颈、肩、腹和圈足形成明确层次，常配覆斗形盖，腹侧可铆接或铸接铺首衔环。方体铸造要求对四壁、转角和盖口配合进行控制。鄂尔多斯博物馆所示四兽钮盖青铜钫即方直口、溜肩、腹微垂、高圈足，盖上另设兽钮。",
        "用途": "钫以盛装酒浆或粮食等物为主，并非直接饮用的杯。汉代自铭“铜钫容六升，重廿九斤”表明至少部分钫兼有明确容量记录，说明它既是容器，也能在管理、储存中表达容量信息。与锺相比，二者都可属壶类盛器，但钫强调方体形制；与量、方升相比，它并非专门的标准计量工具。",
        "使用方式": "使用时从上口注入酒浆或谷物，以盖封口，搬运或倾注时可借助两侧铺首衔环控制器身。若用于宴饮，它承担的是席前储酒、陈置或转盛，不是直接举至口边饮用；若有容量铭文，则可据铭文识别容积，但不能因此把所有钫都视为官定量器。方形器身也使其与圆壶在陈置视觉上有明显区别。",
        "礼仪与制度": "钫可见于战国末至汉代墓葬和饮食器具系统，但现有可靠材料不足以把钫的有无或数量直接换算成固定身份等级。汉代墓葬常以成组饮食器表现墓主生活与礼仪世界，钫可与锺、卮、耳杯等同出。宝鸡主城区文物点资料还记录有汉代“晁阳铜钫出土点”，可确认当地存在此类器物遗存。",
        "史料记载": "《说文解字》释“钫，方锺也”，以“方锺”说明钫与锺在名称、形制上的联系。汉元始四年铜钫器铭有“铜钫容六升，重廿九斤”，同时记录器名、容量和重量，可直接证明汉代“钫”之自名及计量信息。除此之外，暂无足够古代铭文材料支持把所有战国、汉代钫统一规定为某一固定等级或单一使用制度。",
        "器物组合": "钫常处在汉代贮酒和饮食器系统中，可与锺、壶承担较大容量盛装，再与卮、耳杯等个人饮器配合。马王堆类汉墓陈设中，锺、钫与盘、杯、卮可在同一宴饮器用场景出现。若一件钫有容量铭文，也应与专门的升、斗、量器区分：前者主要是盛器，后者以校准容量为核心。"
