        "形制与工艺": "西汉“中山内府”铜锺小口微侈、鼓腹、圈足，无盖，上腹有成对铺首衔环；马王堆遣册又记有带盖的锺，说明盖并非绝对特征。器体通常适于大量盛装，铸造时需处理腹部曲面、圈足和环耳。它与钫的方体不同，与卮的直壁小杯不同，也没有青铜乐钟的合瓦形钟腔和悬挂结构。",
