        "形制与工艺": "盘多作浅腹、圈足并设双耳，大型实例腹面宽阔，底内正适合布置长篇铭文。大口浅壁在浇铸时容易出现铜液汇合不良或底部变形，铸工须控制范腔、壁厚与浇注次序；器耳还要兼顾搬运时的受力。",
