        "使用方式": "行盥时，一人奉盘置于受礼者双手下方，另一人持匜或盉自上而下沃水，洗毕再授巾。盘的位置必须承接水线而不妨碍动作，奉持者的年龄与身份在礼书中亦有区别，说明盥洗过程由多人协作完成。",
        "礼仪与制度": "祭祀、宴飨与婚礼多以洁手开端，盘因而参与的是取得仪式资格的第一道程序。东周墓中盘匜成套随葬日益稳定，数量、材质和铭文随墓主身份而异；它与鼎簋一样，既是器用也是等级关系的物证。",
