        "形制与工艺": "匜通常有槽形流、后鋬和矮足，也见平底器；流口可塑成兽首，纹饰则随时代由兽面、窃曲向瓦纹等样式变化。流槽角度直接影响水束的连续与落点，鋬、器腹和足部必须共同保持倾注时的平衡。",
