        "总介绍": "盉是带管状流、鋬与足的液体调和器，出现很早，二里头文化已有青铜实例。其功能并非始终如一：早期多与酒器同出，常被解释为调节酒水浓淡；西周以后又进入盥洗组合，显示器类会随礼制变化而转职。",
        "形制与工艺": "盉多深腹有盖，前伸管流，后置鋬，下承三足或四足，晚期还出现提梁与兽首流。细长流管需要内芯稳定并保持通畅，流、盖与把手的轴线又关系到倾注平衡；从封顶盉到提梁盉的差异可作为断代线索。",
