        "使用方式": "调酒时可先把水与酒在器中配合，再由管流转注；用作盥器时，持鋬或提梁将温水浇向受礼者双手。足部使器身能够稳定放置，某些实例或可近火温水，但是否直接加热必须依据烟炱与使用痕迹判断。",
        "礼仪与制度": "盉的意义在于控制液体关系：酒礼要求浓淡有节，盥礼要求注水有序，两者都依赖可计量、可重复的操作。器物从酒席转入盥洗场景，也与西周酒器体系收缩、食器和水器地位上升相呼应。",
        "史料记载": "《说文解字》以“调味”释盉，王国维《说盉》进一步提出它是和水于酒、节制厚薄之器，奠定近代名物解释。吴王夫差盉铭文明确见王名与作器语，但所谓专为西施制作属于后世附会，铭文中的女子身份仍不能确证。",
        "器物组合": "二里头至商代的盉多与爵、斝等酒器相伴，说明它靠近调酒和行酒环节；西周以后则常见盉盘配置。春秋时期匜盘逐步替代盉盘，这种搭档更换为判断器类职能变化提供了比单件造型更可靠的证据。"
