        "使用方式": "使用时将水注入宽口盆体，使用者在器内完成手面清洗，或以它承接清洗后的水；双环耳可辅助搬运。由于器口开阔，操作重点是盛水和承水，不需要像鎣那样握鋬由流口向外倾注。国博隋代铜洗出土时内部放置铜镜，说明墓葬埋藏中器内可另置物品，但不能据此改变其盥洗器属性。",
        "礼仪与制度": "现有可靠资料更多把汉代铜洗解释为日常盥洗用具，而非固定等级礼器。商周礼仪中的沃盥常见盘、匜或盘、鎣组合，不能因为功能同属用水，就把后出的“洗”直接替换进西周礼制。若具体墓葬中铜洗与镜、梳妆器或其他生活器同出，应按该墓证据说明其生活或随葬语境。",
