        "器物组合": "铜洗在生活器用中可与铜镜、梳妆用品或其他盥洗器具同处；国博李静训墓铜洗出土时即盛放一面铜镜。若讨论更早的礼仪用水系统，则应另列盘、匜、盉、鎣等器类，不把它们机械合并为“洗”。因此组合说明应区分日常盥洗盆与商周成套沃盥水器两条传统。"
