      "slug": "liang",
      "nameZh": "量",
      "copy": {
        "总介绍": "量是古代度量衡中计量容量的器具总称，所测对象主要是谷物、液体等“多少”，与衡器“权”测轻重不同。秦统一后，中央把既有秦制容量标准推广全国，铜量外壁可刻统一度量衡诏书。“量”是容量计量器的类别名称，不能把所有带容量铭文的壶、锺、钫都归入量器。",
        "形制与工艺": "秦铜量可见椭圆形、长方形等不同器形，关键不在外观是否统一，而在容积受标准控制，并刻有诏文或相关标识。量器制作需要稳定内腔尺寸，使装满后的容量可重复；边口、底壁和内壁形态都会影响实际容积。它与普通盛器的差别，是制造和使用目的指向标准化计量，而非长期贮藏或宴饮陈设。",
        "用途": "量用于确定谷物、液体等物资的容量，是征收、分配、交易和物资管理中的计量工具。中国国家博物馆指出，秦铜量与国家征收粮帛、物资及土木工程计算有关，并属于统一量器标准器具。与方升相比，“量”是较宽的类别，方升则是以“升”为单位的具体标准器；与权相比，量不称重量。",
        "使用方式": "使用时把待测物装入量器内腔，以该器规定的容积作为容量基准，再按单位次数换算数量，或据标准器核验其他日常量具。标准器的作用在于使不同地点使用的同名单位尽量一致。至于颗粒物是否刮平、液面如何判定等具体操作，目前缺乏足够直接材料，不能把后世量法一概前推到秦代器具。",
        "礼仪与制度": "量器与国家制度的关系主要在财政、征收和市场标准，而不是祭祀礼器等级。秦始皇二十六年统一度量衡后，把秦国标准推行全国，诏文直接刻在铜量等器物上，使计量标准与行政命令结合。此类制度背景可明确书写，但不能因此断言每件出土铜量都是中央亲铸，也不能把地方实际执行程度写成完全一致。",
        "史料记载": "秦铜量所刻秦始皇二十六年诏书有“法度量则不壹，歉（嫌）疑者，皆明壹之”等语，明确针对度、量、衡标准不一而要求统一。这类诏文直接铸刻或刻写在量器上，可确认国家政令与标准量器的结合。若某件具体量器没有另刻容量、自名或使用者信息，暂无足够材料为它补出单位数字、官署归属或具体操作规则。",
        "器物组合": "量器在制度上与度器和衡器并列，形成“度量衡”三类：度测长度，量测容量，衡与权测重量。实物使用中，量还可与升、斗、斛等不同容量单位器具构成层级体系。方升属于其中一种具体升量；锺、钫等盛器即使铭有容量，也应先按器物本身功能归类，再说明其容量标识。"
      },
