      "copy": {
        "总介绍": "方升是以“升”为容量单位的方形标准量器，最著名实物为战国商鞅方升。它呈长方槽形并带柄，器壁与底部刻铭，铭文把器腔尺寸与“一升”容量联系起来，后来又加刻秦始皇统一度量衡诏书。它与泛称“量”相比更具体，与钫、锺等盛器相比则以标准容量校准为首要目的。",
        "形制与工艺": "商鞅方升为长方形有柄量器，器腔浅而规整，长边伸出直柄，器壁三面及底部有刻铭。方形内腔便于用长、宽、深建立几何容量关系，制造时尺寸误差会直接改变一升标准，因此其尺度控制比普通盛器更关键。器上早、晚两次铭文又使同一实物保留战国秦制与秦统一后的连续使用信息。",
        "用途": "方升用于确定“一升”的标准容量，可作为官定标准器校准其他升量，进而服务粮食、物资、赋税和交易中的容量核算。它不是用来长期贮酒或陈设的容器，也不是称重用的权。商鞅方升铭文以立方寸规定一升容量，使长度尺度与容量标准发生直接数学联系，可直接说明秦国容量标准如何以器物尺寸落实。",
        "使用方式": "使用时把待测谷物或液体装入方形内腔，以其规定容积作为一升，再按次数换算更大容量。作为标准器，它还可用于检验或复制日常量具，而不是只完成一次测量。具体操作中的平口方法、液面判定等细节，目前公开可靠资料不足，不应自行补写；可确定的是其内腔尺寸被设计为对应法定一升。",
        "礼仪与制度": "方升属于国家计量制度，不属于宗庙礼乐器。秦孝公时期商鞅推行统一度量衡，方升作为标准量器服务秦国内部管理；秦始皇统一六国后又在同器底部加刻二十六年诏书，说明旧秦标准继续被纳入全国统一体系。其制度核心在“同量”，不能把它描述成祭祀用礼器或贵族身份象征。",
        "史料记载": "商鞅方升器铭记秦孝公十八年“大良造鞅”并有“爰积十六尊（寸）五分尊（寸）壹为升”，以十六又五分之一立方寸规定一升容量；秦始皇二十六年又在同器加刻统一度量衡诏文。两层古代铭文同存于一器，可直接说明秦国至秦朝容量标准的延续，无需借后世传说补写其用途或制度。",
        "器物组合": "方升属于升、斗、斛等容量量器体系中的“升”级标准器，可与更大或更小容量单位共同承担物资核算。它在制度上又与尺等度器、权衡等衡器并列。与普通钫、锺相比，方升的器腔尺寸就是标准本身；与泛称铜量相比，它是一个有明确单位名称和著名自铭实物的具体类型。"
      },
