      "slug": "quan",
      "nameZh": "权",
      "copy": {
        "总介绍": "权是衡器中的秤锤或砝码，用来与衡杆、天平等配合测定物体重量。战国秦汉铜权形态多样，可为环形、钟形、瓜棱形等，关键特征是自身重量被校准，并常有重量单位或诏文。它与“量”测容量完全不同；与一般悬坠物的区别，则在于权的质量承担计量标准功能。",
        "形制与工艺": "秦权可见实心或空心、圆体或多棱体，顶部常有钮或环，便于悬挂；“八斤铜权”铸有“八斤”并刻统一度量衡诏书。后世还有扁平环权。制造时既要控制外形，更要通过材料和修整把实际质量校准到目标值；因此器物表面文字与实测重量常是研究古代斤、两换算的直接依据。",
        "用途": "权用于称量轻重，与衡杆配合时通过移动位置取得平衡，与天平配合时则以已知质量和待测物比较。秦权服务赋税、仓储、交易和官府管理，其作用是统一重量标准，而非盛装物品。现代词“权衡”即保留了权与衡配合的概念，但具体古代称量结构应按实物类型区分，不能把所有权都想象成同一种杆秤砣。",
        "使用方式": "使用时把权悬在衡杆规定位置或置于天平一端，与待称物反复调节至平衡，再按权的质量和杆上尺度读出重量。带钮、环的造型适合悬系。不同制度和器型的具体读数方法可能不同，因此只能确认平衡称量这一基本动作，不能为战国、秦、汉各类权统一补上同一种秤杆结构或固定悬挂点。",
        "礼仪与制度": "权直接关系官府统一衡制。秦始皇二十六年诏书被刻、铸或嵌附在权上，说明重量标准以行政法令向全国推行；秦二世又重申相关诏令。此类器物因此兼具计量和政令载体性质，但制度说明应落到“统一标准、官府颁布”层面，不把每件无铭铜权都认定为中央标准器，也不延伸为礼仪等级物。",
        "史料记载": "秦“八斤铜权”器上铸有“八斤”，并刻秦始皇二十六年统一度量衡诏书，诏文有“法度量则不壹……皆明壹之”等语。《史记·秦始皇本纪》又记“一法度衡石丈尺”。器物自铭、诏书与传世史籍都能证明秦统一重量标准的政策背景；对某一无铭铜权的具体斤数、官署或称量口诀，暂无足够材料，不作补写。",
        "器物组合": "权必须与衡器系统中的衡杆、天平、绳系或秤盘等部件配合才完成称重；单独一枚权只是已知质量的标准部件。制度上它与尺类度器、升斗类量器并列为度量衡体系。若成组出土多个不同重量的权，可形成重量序列；若仅一件，则不能凭孤器推断完整秤具的所有构件。"
      },
