      "slug": "zhong",
      "nameZh": "钟",
      "sourceHeadingIndex": 309,
      "copy": {
        "总介绍": "先秦青铜钟以成组悬挂和可控音高为核心，是宗庙祭祀、诸侯宴飨与权力陈设共同使用的乐器。西周以来，编钟数量、悬挂方式和铭文内容逐渐制度化；曾侯乙编钟保存六十五件及大量乐律铭文，使这一声音制度获得异常完整的实物证据。",
        "形制与工艺": "钟腔截面多呈合瓦形，甬钟以甬部斜悬，钮钟则凭顶部钮直悬，钟口和鼓部结构影响振动方式。合瓦形器体可在正鼓与侧鼓产生不同音高，铸后又可通过磨砺局部调音；一钟双音是形制、合金和校音共同作用的结果。",
        "用途": "编钟用于奏礼乐、宴乐和典礼信号，某些大型钟还兼具聚众、报时或纪事功能，但不宜将后世寺院钟的职能全部倒推到先秦。钟与鼎分别组织声音和饮食的等级，两套器物并置时，礼制通过可听与可见的方式同时展开。",
        "使用方式": "钟按音高和体量悬于簨虡，乐工以木槌击正鼓或侧鼓，大钟可另用撞木，演奏需要多人按声部分工。曾侯乙墓同出钟架构件、槌具及音名铭文，使悬挂、击奏和音高对应可以互相验证，而非仅靠复原想象。",
        "礼仪与制度": "乐悬制度以悬挂面的数量区分王、诸侯、卿大夫与士，声音空间本身因此成为等级标志。春秋战国诸侯扩大钟列、铭刻祖功或交往信息，既延续宗庙礼乐，也参与竞争性政治表达；僭越与创新常在同一套乐器上并存。",
        "史料记载": "《周礼·考工记》“凫氏为钟”讨论器体比例与声音疾徐，是理解先秦钟制的重要技术文本；《周礼·春官·小胥》又载宫悬、轩悬、判悬、特悬等等级。曾侯乙钟铭补充音名与律制对应，文献规范和地方实践由此可以对读。",
        "器物组合": "编钟通常与编磬、建鼓、瑟、笙等构成金石丝竹合奏系统，不同乐器负责起止、节奏与音色层次。宝鸡太公庙窖藏的秦公钟与秦公镈同出，铭文追述秦人受命立国，说明乐器组既是演奏编制，也是保存族国叙事的整体档案。"
      }
