        "总介绍": "镈是体量较大、口沿趋平的悬击青铜乐器，可单悬，也可多件编列，常与钟磬共同承担礼乐低音。它与甬钟关系密切，却不能只按“大号钟”理解；平口、钮部、腔体比例和自名铭文共同构成分类依据。",
        "形制与工艺": "镈多具环钮或兽钮，腔体宽厚，正鼓面积大，器壁质量决定低音是否稳定。宝鸡太公庙秦公镈三件体量递次并有长铭，铸后还需通过修磨调节音高；大型腔体一次浇注的充型和冷却控制尤其困难。",
