        "史料记载": "《左传·襄公十一年》记郑国所献“歌钟二肆，及其镈、磬”，证明镈是高规格乐器组合的一部分。《说文解字》释镈为“博钟”，只提供形体宽博的概括；具体器类仍要依金文自名和考古形制加以限定。",
