        "总介绍": "编镈是把多件镈按大小或音高成组配置的青铜乐器。镈属于先秦乐钟系统，常见平口，顶部以钮悬挂，器体可有中脊、扉棱、枚和繁复纹饰；与甬钟相比，其顶部悬挂结构和口缘形态不同。宝鸡太公庙秦公器群由三件镈与五件钟同出，是说明编镈与编钟协同使用的直接实例。",
