        "用途": "编镈用于成组击奏，并可与甬钟、钮钟等配置在同一钟乐器群中。具体音域、音列和每件器物承担的声部随器群而异，不应把某一套镈的测音结果推广到全部编镈。它与编钟关系密切，但“镈”本身是一种钟形类型；与编铙相比，镈通常悬挂后器口向下，再由外部击奏发声。",
        "使用方式": "演奏时把各镈通过顶部钮悬挂在架上，器口朝下，以槌击指定部位发声；多件镈按大小、音高或编组次序依次排列。宝鸡秦公三镈与五钟同坑有序摆放，说明实际使用并非孤立单器。由于不同镈的声学性能尚需具体测音，通类说明不应预设每件都能双音或固定承担某一音级。",
        "礼仪与制度": "镈属于先秦礼乐器，常见于高等级墓葬、祭祀坑或青铜乐器窖藏，并可与钟、磬构成乐悬。宝鸡太公庙器群被国博资料解释为春秋秦武公时期祭祀遗址，三镈五钟成套且都有铭文。可据此说明秦国贵族礼乐使用，但不能据这一个器群推定“某爵位必用三镈”的普遍制度。",
        "史料记载": "宝鸡太公庙三件秦公镈均有铭文，三器文字可连读，内容追述秦公室先祖及作器者，并有祈福语；曾侯乙墓大镈另有楚王赠器铭文。两类金文都直接刻铸在镈体上，可用于说明作器、世系和赠器关系。对未见于铭文的具体演奏曲目、固定音级或爵位配额，暂无足够材料，不从后世礼书反推。",
        "器物组合": "编镈常与甬钟、钮钟等乐钟处在同一礼乐器群中，也可再与编磬、鼓等配合。宝鸡太公庙的可核实组合是五件甬钟加三件镈，器物有序同出且均有铭文，这已经能说明镈与钟并非同名异器，而是可在同一钟乐系统中分列的不同形制。至于其他墓葬的件数和比例，应按各自器群另行确认。"
