        "形制与工艺": "铎的关键结构不是外纹，而是“柄—器腔—内舌”三部分：顶部可有方孔纳木柄，器内设钩悬舌，器身短阔或呈合瓦形，口部可内凹。印山越王陵铜铎甚至保存木柄、木舌。铸造时需让腔体足以被舌撞击振动，并使柄孔、悬舌构件牢固，这与编钟依靠外部钟架悬挂完全不同。",
