        "使用方式": "操作者握住上部木柄或柄部，往复摇动铎体，使悬在内部的木舌或金属舌撞击器壁发声；需要宣令时，文献还记有持木铎巡行道路的动作。木舌与金属舌在材料上不同，郑玄注又分别把木铎、金铎联系到文事和武事。它依靠内舌撞壁发声，与钟、铙从外部敲击器体的方式不同。",
        "礼仪与制度": "古代制度文献把铎纳入政令与军旅秩序，而不是单纯宫廷乐舞。郑玄注《周礼》有“文事奋木铎，武事奋金铎”的解释；《尚书·胤征》又记遒人以木铎徇路、宣布政令。考古中铎与兵器同出也提示军事用途。具体到某件铜铎是否属文铎或武铎，仍须看内舌材质和出土背景。",
