        "总介绍": "句鑃是吴越地区特别突出的青铜击奏器，器名主要由出土器物自铭确认，并非先秦传世典籍中的常见名称。器体狭长，口部内凹成弧，双铣尖锐，上有柄，使用时口朝上，可插植器架或地面后以槌敲击。它与甬钟的悬挂口朝下、铎的内舌摇击都明显不同。",
