        "礼仪与制度": "句鑃在吴越及岭南材料中可与祭祀、宴飨和宫廷音乐相联系，但现有证据不支持把其件数直接对应中原周礼的固定爵级。绍兴、无锡等地材料显示其有鲜明地域传统，南越国又继续使用并由乐府制造。可写“贵族或宫廷礼乐器”，却不应据后世礼书为句鑃套入未经证实的乐悬等级。",
