        "总介绍": "铜鼓是以青铜铸成、鼓面与鼓身连为一体的打击乐器，主要流行于中国南方和西南地区。典型器形有平展鼓面、中空鼓腹、束腰或胴部、敞足，侧面可设扁耳，鼓面中央常饰太阳芒纹。它与皮鼓不同，不覆革膜；也与钟、铙不同，主要敲击水平鼓面而非钟形腔体。",
        "形制与工艺": "铜鼓通常整体铸造，鼓面为主要发声面，中部可铸多芒太阳纹，周围分晕布置几何、云雷、羽人、舟船或动物纹；鼓身中空，两侧可有双耳，底部敞开。国博藏铜鼓为九晕、十二芒，鼓身有双扁耳。大体量薄壁中空铸件对合金、范铸和壁厚控制要求高，但不同类型铜鼓形制差异明显。",
        "用途": "铜鼓可用于歌舞伴奏、祭祀、传信报时等，不同民族和时代的功能不完全相同。国家民委资料明确列出祭祀、乐鼓伴奏、传信报时等用途；国博则把一件铜鼓说明为西南少数民族常用歌舞乐器。它不应被简单纳入中原周代编钟乐悬，也不能把所有鼓面纹饰都解释为同一宗教含义。",
