        "礼仪与制度": "铜鼓在南方、西南多民族社会中兼有乐器、祭仪器以及财富、权势相关器物的属性，但其制度逻辑与中原列鼎、乐悬不同。不同地区、类型和时代可见祭祀、歌舞、传信、报时等用法。它应作为区域性青铜乐器理解，不能因为同为青铜打击乐器，就把铜鼓硬套入西周宗庙钟磬的等级体系。",
        "史料记载": "《后汉书·马援传》有马援在交趾得骆越铜鼓并据其铸马式的记载；《隋书·地理志》记岭南“贵铜鼓，岭南二十五郡处处有之”。两条传世文献可以确认汉至隋时期南方铜鼓的存在及其受到重视的社会背景。至于更早铜鼓的自名、固定演奏动作或等级制度，目前暂无足够同时代器铭材料，不把后世记载直接前推。",
        "器物组合": "铜鼓可处在歌舞、祭仪和信号活动的器用组合中，但各地区的考古配伍差别很大，不能设定统一套数。它不像编钟、编磬那样通常以多件固定音高组成音列，也不像句鑃、编铙以一组大小递减器体成编。铜鼓的核心结构是单个中空青铜鼓体和水平鼓面，因此其组合逻辑应与中原钟磬乐器分开理解。"
