        "总介绍": "磬是硬质石材制成的悬挂击奏乐器，先秦“八音”分类中属“石”，不是青铜器。早期单体石磬多呈不规则三角或逐渐规整的片状形态，上部钻孔以绳悬挂，击打器体发声。它与青铜钟、镈同属礼乐打击器，却在材质、制作方法和音色上完全不同，只能作为青铜礼乐系统的相邻材料处理。",
        "形制与工艺": "早期石磬可由石料打制、磨制成片状器体，上缘或近上部钻一孔供悬挂；后世磬形逐渐规整，需通过选石、修整厚薄和敲击测试控制音高。国博一件石磬呈三角形，器表保留打制痕迹，上方有圆穿。与青铜钟范铸不同，磬的声学调整依靠石材尺寸、厚度和轮廓修整，不能套用铜器铸造术语。",
        "用途": "磬用于悬挂后以槌敲击发声，可单件使用，也可发展为大小相次的编磬。商周以后它常与钟、鼓等共同参与礼仪音乐，形成“金石”并举的声响。它不盛放食物、酒水，也没有青铜容器的实用功能；与铜制乐钟的区别不仅是材质，还包括发声体为石片本身而非中空金属腔体。",
        "使用方式": "演奏前用绳索穿过器体圆孔，把磬悬在架上，使石片处于可自由振动的状态，再用槌敲击器体发声。单磬提供的音高数量有限，成编后则由多件不同尺寸的磬构成音列。它不像铎那样靠内舌摇响，也不像青铜钟以中空金属腔体发声；具体击点与音高关系仍须依据实物测音。",
        "礼仪与制度": "磬在先秦礼乐中有明确位置，常与钟等乐器并用于礼仪；但“磬”不是青铜器分类中的一个铜器门类。古代“八音”中的“石”即以磬为代表，《周礼》又设磬师职掌。因而可把它放在钟磬礼乐关系中讨论，同时必须保持材质边界：此处所述石磬属于非青铜相邻材料。",
        "史料记载": "《周礼·春官》设有“磬师”职掌，《礼记·乐记》又有“石声磬”等论述，把磬明确归入礼乐声音体系。这些古代文献可以确认“磬”之名、石质声类和礼乐角色。对于某一件无铭出土石磬，文献并不能直接给出墓主身份、实际演奏曲目或具体音高；这些内容若无铭文或测音证据，暂无足够材料，不作补写。",
