        "礼仪与制度": "编磬常见于高等级先秦墓葬和礼乐场合，可与编钟同时出现，但具体等级不能仅由“有编磬”三字确定。陕县后川墓十件编磬出自规模较大的战国墓葬，曾侯乙墓又保存更复杂的钟磬系统。这些实例能够说明编磬与高等级礼乐资源的关系，却不能把后世整理的乐悬条文机械套到所有先秦墓葬。",
