      "copy": {
        "总介绍": "挹酒之斗是长柄勺形器，用于从深腹尊罍中舀取酒液，与容量单位“斗”同名但不属于同一器类。北斗因星列近似带柄斗形而得名，《诗经》又借天上的斗不能挹酒发问，日常器具由此进入古人的星空想象。",
        "形制与工艺": "此类斗由圆深勺体和长柄构成，柄可直可曲，末端常饰兽首或环，长度适合探入大型酒容器。柄勺连接处承受反复起落，需要在轻便与强度之间取得平衡；曲柄角度还能让手部远离尊口，避免沾酒。",
        "用途": "斗承担从储酒器向爵、觚等饮器转移液体的中间环节，大容量器不能直接倾倒时尤其必要。它也可能参与调酒或按份斟酌，具体用途取决于勺体容量和同出器物；后世量斗名称或与舀取动作相关，但词源仍需谨慎表述。",
        "使用方式": "宴礼中，斗可横置尊口或放在近旁，用时握柄探入酒面，提起后平移至饮器上方再倾注。长柄扩大了动作半径，也要求操作者控制勺体摆动；器柄上的磨损、修补和断裂位置能够提供真实使用频率的线索。",
        "礼仪与制度": "斗自身不标示高等级，却是酒礼流程不可缺少的传递工具，说明制度不仅由重器构成，也依赖辅助器具。礼书所见尊上加勺与考古组合相互印证，器物位置固定后，谁执斗、向谁行酒便成为宾主秩序的一部分。",
        "史料记载": "《诗经·小雅·大东》说“维北有斗，不可以挹酒浆”，以挹酒器反衬星宿徒具其形；《大雅·行苇》又有“酌以大斗”，置于敬老宴饮。两条诗证分别保存比喻与实景，却没有给出铜斗的精确形制，仍需实物补充。",
        "器物组合": "挹酒斗通常邻近尊、罍、卣等深腹盛酒器，并与爵、觚组成从储存、舀取到饮用的连续链条。它与较小的勺在尺寸和柄形上有交叉，考古定名有时并不统一；组合功能比僵硬划线更能说明两者关系。"
      }
