      "copy": {
        "总介绍": "勺是小型挹取器，常见于酒尊之侧，也可用于羹汤等液态食物，其基本动作是从大容器向小容器分配。它与长柄斗形制相近，二者界线未必始终清楚；“勺”后来又成为容量和日常餐具名称，显示器名具有很强延续性。",
        "形制与工艺": "青铜勺多作圆形或椭圆勺体，配较短柄，柄端可平直、带环或饰兽首，器壁通常薄于大型容器。小器铸造虽耗铜不多，勺壁均匀、柄勺夹角与连接强度却直接决定是否好用，细部修整比纹饰繁简更重要。",
        "用途": "在酒礼中，勺从尊、壶内少量挹酒，适合临席添注或按杯分配；在饮食环境中，也可能舀取羹液和湿食。仅凭单件外形难以区分酒勺与食勺，残留物、出土位置和相邻器类才是判断功能的关键。",
        "使用方式": "礼书所谓“加勺于尊”，说明勺在未使用时安放于盛酒器口沿或指定一侧，取用后还要复归原位。执柄探液、抬起平移、贴近杯口倾注是一组连续动作，柄部长期磨光往往比器面纹饰更直接地记录操作者。",
        "礼仪与制度": "勺的制度意义来自位置和操作者，而非自身规模：尊设在哪里、勺朝向哪一侧，都服务于宾主分位和行酒次序。辅助器具把宏观礼法转成可执行动作，也提醒研究者不要只凭鼎钟等重器重建礼仪现场。",
        "史料记载": "《说文解字》以“挹取”释勺，准确抓住其动作性质；《仪礼》多次记录尊上加勺，为器物陈设提供了连续文本证据。文献往往只说功能与位置，不足以确定每一件出土勺的用途，因此仍须与器形和组合互证。",
        "器物组合": "勺常伴随尊、壶及饮酒器出现，与较大的挹酒斗形成容量上的互补，也可能进入食器群。由于小件在墓葬中容易移位、朽损或被忽略，统计组合时应核对发掘记录；缺见勺并不必然代表原有仪程不需分液工具。"
      }
