        "总介绍": "匕的核心功能是取食与分食。典型器形为长柄浅斗，近似羹匙，考古材料中还可见适合分肉、进食或滤取羹中固形物的不同形态。它与短刀、短剑共享部分名称传统，但识别时必须回到浅斗、刃部和使用组合。",
        "形制与工艺": "国博将典型匕概括为长柄浅斗；另有尖头、较小浅斗或镂空匕头等变化。铜匕可以铸出柄、斗和装饰，骨、牙、漆木材质也有对应实例。所谓匕形器只有在斗部可容纳食物且结构适于持握时，才宜进一步讨论取食功能。",
        "用途": "匕可从鼎、鬲等容器中挹取熟食，也可承担分肉、进食或滤取羹中肉块的动作。不同尺寸和匕头结构提示用途存在细分，不能把取食、切割、搅拌和兵器功能无条件并列为每一件匕都具备的用途。",
        "使用方式": "使用者握持长柄，将浅斗伸入盛食器内舀取，再转移到俎、案或个人食器。尖头或较大的器形可能参与分肉，镂空匕头则更适合让汤汁漏下。动作链应表现器物与食物、盛食器之间的接触，而不是挥刺姿势。",
        "礼仪与制度": "匕可进入贵族宴飨和祭祀分食场景，考古中常与鼎、鬲同出，说明它是器物组合中的操作工具。材质珍贵或装饰复杂可以反映使用环境，但不能仅凭铜、金或象牙材质推定器主等级，也不能把所有食匕都称为礼器。",
        "史料记载": "故宫词条明确称匕为取食器，作用近似今天的匙，并指出考古发现常与鼎、鬲同出。国家博物馆又以长柄浅斗概括典型形态，同时提醒某些外形相似的匕形器并不适合盛汤盛饭，可能属于仪式用具或饰物。",
        "器物组合": "匕与鼎、鬲、簋、俎和案形成从烹煮到分食的动作链：先由盛煮器取出食物，再在俎或案面完成分置。若匕与兵器、佩带附件同出而缺少食器组合，则应重新检查定名，不可只凭名称归入饮食系统。"
