        "史料记载": "故宫祼礼词条引述礼书对祼祭、祼飨及圭瓒的说明；中国社会科学院考古研究所报道指出，殷墟卜辞中的祼礼以瓒为实施礼器，并因器柄名玉而称玉瓒。现有来源支持功能与名物关系，仍不足以确定圭瓒唯一的标准形制。",
