        "形制与工艺": "汉代案多见长方形案面，下装柱状或蹄状足。战国中山国错金银四龙四凤铜方案座以鹿足、龙凤构件和上部承托结构组成复杂铜座，显示铸造、错金银与多部件连接工艺，但案面材质不能凭铜座臆定。",
        "用途": "案置于席前，供坐者近距离陈放和取用饮食器、文具或其他小件。它提供相对平整、稳定的承物表面，功能范围比俎和器座更广。具体是食案、书案还是祭案，必须由同出物和空间位置区分。",
        "使用方式": "使用者席地跪坐或盘坐，案面处于手臂易及高度，可把杯盘依次放置、取下。若只保存铜足或方案座，复原时应把缺失的上部标明为推定构件，并避免把承托座直接当作可放物的案面。",
