        "形制与工艺": "器座可见环形承托面、足部、束腰、孔洞或镂空座体。国博著录战国早期虎足器座，另有王湾镂孔陶器座展示折沿、束腰和多层镂空结构。两例只说明器座形态多样，不能互相复制材质和细节。",
        "用途": "器座把上置器物抬离地面，扩大受力面并保持稳定，也可形成适合礼仪陈设的高度与视觉中心。具体承托的是容器、乐器还是其他物件，需要接口、足窝、磨痕、同出位置或可复原组合提供证据。",
        "使用方式": "先将器座平稳放置，再把上置器物的底、足或柄嵌入承托面、凹槽或孔口。器座的关键在于上下两件之间的受力关系。若上置器物已经缺失，只宜展示可能的安装方向，不应补造具体器类。",
        "礼仪与制度": "部分器座造型和装饰接近礼器，并可能用于礼仪活动，但承托功能本身不等于礼器身份。器座是否进入祭祀、宴飨或乐舞陈设，应由上置器、墓葬位置和成组器物说明，不能仅凭纹饰庄重判断。",
