        "器物组合": "器座必须在上下组合中理解：承托面对应上置器物底部，足部对应地面。它与案的区别在于不直接为人提供广泛陈置面，与圈足的区别在于圈足属于器身。后世收藏家另配底座不能冒充考古原组合。"
