        "史料记载": "故宫研究资料概括了镜面抛光、背面纹饰和钮等传统特征；鄂州政府馆藏介绍通过具体神兽镜的分区图像与铭文，说明镜背承载时代观念。现有来源支持结构和图像分析，不支持所有镜均为圆形或同一用途。",
