        "形制与工艺": "博山炉常在盖上塑造层叠山峦，并依山势开设镂孔，烟气由孔道逸出；有的配圈足、承盘、三足或细长柄。竹节柄铜熏炉还可分铸炉体、柄和座再铆接，显示透雕、鎏金银和复合装配。",
