        "总介绍": "盒是由盒身与可开合盒盖构成的广义收纳器，形状、分格和扣合方式随用途变化。某些春秋青铜盒经残留物检测可确认曾盛油脂、植物精油和矿物颜料，但这一证据不能推广到所有盒。",
        "形制与工艺": "青铜盒通常具有相互配合的口沿和盖，可能呈圆形、方形或其他几何形，表面可铸纹、错嵌或加附件。北白鹅墓地成组青铜盒形态丰富，说明盒不是单一模型。内部腐蚀层和残留物还可保留使用线索。",
