        "形制与工艺": "钩首向前弯曲以完成扣合，背钮把钩身固定在带端或皮革上。钩身可细长、宽扁或作动物形，表面使用铸造、错金银、鎏金、镶嵌等工艺。不同尺寸和钮位会影响佩带方式，不能设定唯一方向。",
