        "使用方式": "背钮穿入或固定在带体一端，钩首再钩住另一端的孔、环或带体，受力后保持闭合。解开时先解除钩首。钩、钮和皮带共同构成连接关系，正面纹饰不能脱离背部结构单独理解。",
