        "形制与工艺": "鄂君启金节呈竹节剖面状，以青铜铸体并错入金字，现存车节和舟节。形制既便于持有和出示，也把长篇规则固定在耐久金属表面。其他铜节可能在外形、铭文和验证方式上不同，不能一概而论。",
        "用途": "持节者凭此经过规定区域、关津或运输线路，并依铭文接受车辆、舟船数量、货物种类和征税待遇的查验。它是有条件的行政许可，并非脱离路线、期限和身份限制的普遍免税牌。",
        "使用方式": "通行者携带铜节，在关津或管理节点出示；查验者核对节上文字与实际车舟、路线和货物，再决定放行及税费。可确认的动作包括持节、验读和通行；现有来源未见合符程序。",
