        "形制与工艺": "漏壶具有储水或受水容器、出水孔道及控制水流的构件；多级系统以数壶依次补水，末端受水壶设浮舟和带刻度箭杆。壶数、孔位、标尺和支架随时代而变，不能统一画成四壶。",
        "用途": "漏壶用于昼夜计时和更次管理，水位随时间改变，刻度将变化转成时刻读数。它可服务于城楼报时、宫廷或公共时间秩序，但精度受流速、水温和水头影响，需要校准，不能描述为现代精密钟。",
        "使用方式": "向上级壶加水，水经孔道以尽量稳定的速度流入下一级或受水壶；浮舟随水面升高，刻度箭杆逐渐显露，值守者读取刻度并报时。使用者还要补水、调流和校准，不能只展示静止壶体。",
        "礼仪与制度": "漏壶属于计时技术，也与官署值更、城市报时和秩序管理相联。是否用于宫廷、军营或钟鼓楼，应以发现年代和使用地点确定。复杂多级铜漏壶反映资源投入，但不等于单独的身份礼器。",
        "史料记载": "北京市文物局资料说明更漏又称铜壶滴漏、漏壶或刻漏，并介绍浮箭百刻及与日晷校准；钟鼓楼资料展示多壶递水机制。来源支持计时原理和具体系统，未证明所有漏壶都有外露百刻或相同壶数。",
        "器物组合": "完整漏刻由储水壶、受水壶、孔道、浮舟、刻度杆和支架组成，必要时与日晷等校时器配合。普通铜壶即使有流或孔，也需出现稳定滴水和读数结构，才能排除储水、注水等其他用途。"
