        "使用方式": "把燃炭或热炭置入勺形器腹，握住长柄使受热底面在织物上移动或短暂停留。操作者需控制热量和接触时间，避免灼伤织物。炭置于器腹，受热底面接触布帛，织物不直接接触火焰。",
        "礼仪与制度": "熨斗属于衣物整理和纺织生活工具，进入墓葬时可反映服饰维护与家庭生活。精美兽首柄和铜质工艺显示审美与制作水平，但不能限定为女性用品、宫廷专器，也不能把随葬解释为礼仪使用。",
        "史料记载": "甘肃文旅页面给出武威铜龙首柄熨斗的汉代年代、尺寸、圆口圆腹、长柄、焊接和器内炭迹，并将其联系到熨帛。巩义市政府另确认汉晋兽首架铜熨斗组合，支持器类存在配架形态。",
        "器物组合": "熨斗可与置放架、衣帛和炭火工具形成使用组合；器内炭迹、柄部隔热距离和底面磨损共同支持功能。若只有长柄勺形铜器，应与鐎斗、灯和匕比较受火位置、足部、容量及接触面。"
