      "nameZh": "镳",
      "copy": {
        "总介绍": "马镳是位于马嘴两侧、与衔端相接的颊侧构件，可限制衔横向滑移，并为络头或辔绳提供连接位置。镳常与衔成副出土，形态可为长条、S形、桨叶端或兽形，不应单独画入口内。",
        "形制与工艺": "阳信墓鎏金衔镳中，镳穿在衔两端铜环内；一类镳略呈S形，两端近桨叶，中段有横穿孔。不同实例可铸动物纹、鎏金或改变孔位。镳的长度和孔环结构须与衔、颊带匹配。",
        "用途": "镳在马口角外侧稳定衔的位置，避免衔过度横向移动，并协助连接颊带和辔具。它与衔共同把驾御动作传递给马头。单独的镳不能完成控马，装饰华丽也不改变其作为辔具连接件的基本属性。",
        "使用方式": "把镳穿接在衔两端的环上，使其沿马颊外侧纵向或斜向展开，再通过中部孔、端部或附环连接皮革颊带。镳在口外、衔在口内，二者还需颊带和缰绳连接。",
        "礼仪与制度": "衔镳的材质、鎏金和纹饰可以表现高等级车马装备。成组数量和墓葬位置还能说明驾马匹数，但不能由一副精美镳推定王侯身份，也不能把“分道扬镳”的成语故事当作器物制度证据。",
        "史料记载": "陕西地方志官方资料对阳信墓十副鎏金衔镳及镳穿衔环、S形、桨叶端和横孔有具体记录；琉璃河官方资料将衔镳列为核心车马器。来源支持结构组合，没有证明所有镳直接连接驾御者手中缰绳。",
        "器物组合": "镳必须同衔、颊带和缰绳组合理解，两件通常分置马口两侧。它与当卢、节约和泡饰的位置、受力方式不同。若兽形或条形铜件没有与衔环配合的孔道，应先排除带饰、车饰和兵器附件。"
      },
