      "copy": {
        "总介绍": "盖弓帽是套在车盖弓条端部的小型帽状或管状金属件，用于包护弓条末端并参与车盖边缘连接。木、竹车盖易朽，成组盖弓帽的数量和车厢附近位置常成为复原伞状车盖的重要证据。",
        "形制与工艺": "盖弓帽体量小，内部有容纳弓条端部的孔腔，外部可作帽形、管形并加装饰。邯郸战国车马坑在车厢附近发现十八件盖弓帽和两件三通管，据此判断存在伞状盖。单件形态不能代表固定数量。",
        "用途": "盖弓帽保护木竹弓条易裂、易磨损的末端，也可能帮助弓条同盖面或边缘构件保持稳定。它不是整副车盖的承重中心，完整伞盖还需要盖杆、盖斗、弓条、织物和连接件共同完成。",
        "使用方式": "把帽件套在放射状盖弓的外端，使各弓条末端获得包护，再与盖面边缘相接。多件围绕车厢成组分布时可推知伞状轮廓。盖弓帽安装在车盖弓端，不能误装到车轴、车辕或马具。",
        "礼仪与制度": "带伞盖车辆可参与身份与出行仪仗，鎏金盖弓帽还会强化视觉等级。具体车辆是否属于王侯、乘舆或仪仗车，应由车马坑、墓葬和整车构造判断，不能由一枚帽件或十八件这一孤例直接定级。",
        "史料记载": "河北省文物局明确记录车厢附近十八件盖弓帽、两件三通管，并据此判断车顶有伞状盖。重庆市政府另列车轴饰、伞箍、盖弓帽等成组车马器。资料支持端部构件和组合推断，没有统一古文定式。",
        "器物组合": "盖弓帽应与盖弓、盖杆、盖斗、伞箍和盖面织物共同复原。它与伞箍的管件连接位置不同，也与衡帽、辕饰等其他端帽分属不同系统。无原位的小套筒必须比较孔径、数量和分布再定名。"
      },
