        "形制与工艺": "该器长46.3厘米、重7千克，两端相通，筒内设隔挡；近一端的相邻两面各铸三枚锯齿，另一端两面开口。正面与底面满饰蟠虺式龙纹，其余部位留出安装面，整体铸造同时解决套接、受力和表面装饰。",
        "用途": "方筒、隔挡与齿缘共同指向木构节点的包护和连接：中空部分可容纳木质构件，隔挡限制插入深度，齿部增加端部咬合。馆方将其定为建筑构件，但它究竟位于梁端、转角还是其他节点，现有资料尚不能唯一确定。",
        "使用方式": "安装时先按方筒内腔选择相应截面的木件，使木端插入并抵达内部隔挡，再让齿状一端贴合相邻构件或节点表面。器上各面并非同等装饰，朝向可能与可见面有关；缺少原位木痕和完整建筑基址时，不宜固定其上下方向。",
        "礼仪与制度": "用七千克青铜铸成大型、带连续纹饰的建筑节点，说明施工者把昂贵金属投入具有展示性的木构工程。它可反映春秋秦地铸造与营建技术的结合，却不足以单独证明建筑必为宫殿、宗庙，也不能据纹饰直接判定使用者等级。",
        "史料记载": "宝鸡青铜器博物院公开了器名、年代、出土地、尺寸与各面的结构描述；国家博物馆对青铜釭的著录说明，商周大型木构件常以铜件包接或加固。两类资料共同支持建筑属性，尚未提供这一方筒在原建筑中的确切部位记录。",
        "器物组合": "它应与截面相合的木梁、柱或枋形成实际装配关系，附近若有钉、铆件或其他铜套，可进一步还原节点。豆腐村另见楔形龙纹铜构件，但两件形态和孔位不同；没有接合痕迹、同一位置记录或力学吻合，不能直接拼成一组。"
