        "形制与工艺": "器长31厘米、宽20厘米、重5.75千克，纵向呈等腰梯形，内部中空。上部中央有直径约4厘米的圆形铆孔，后部和颈部另设较小孔位；正面、底面铸蟠虺式龙纹，其他面较素，便于贴合或遮蔽。",
        "用途": "楔形轮廓适合填补、包护或锁定具有斜面的建筑节点，大小不同的孔可供销钉或铆件穿接，使铜件与木材不易滑移。其建筑附件身份有馆方定名支持，具体是转角、梁端还是斜撑部位，仍取决于失佚的木构环境。",
        "使用方式": "施工时可先把空心器体套入或贴合经加工的木端，再通过中央大孔和后部小孔穿入连接件，将楔面压紧。纹饰集中在正面、底面，提示至少部分表面可能外露；若未发现孔内残留物，不能断言所用一定是铜铆钉。",
