        "史料记载": "宝鸡青铜器博物院条目给出1973年凤翔豆腐村的发现信息，并逐项说明梯形截面、空腔、三处孔位和饰纹面。国家博物馆所释青铜釭提供铜件包接木构的比较材料，但没有记载两件豆腐村构件曾彼此相连。",
