        "总介绍": "铺首是固定在门扉、棺椁或器壁表面的承环座，常把兽面造型、衔环孔和连接部合为一体。它可以配活动铜环，也有环已失落的遗例；辨认重点是固定底座承担拉力的结构，不能把所有兽面纹饰或独立圆环都叫铺首。",
        "形制与工艺": "常见做法是铸出隆起兽面，在口鼻附近设置横穿或垂直的环孔，背面另有钉脚、铆榫或贴合面。细部可再施鎏金、错金银或錾刻。不同年代并无统一脸谱，耳、角、眉和鼻梁的变化只能用于分期比较。",
        "用途": "装在门上时，铺首承接门环的牵拉和叩击，遮蔽环轴与木门的连接处，同时形成醒目的门面装饰；装在棺椁或容器上时，它也可能只负责系挂、提持或象征性陈设，不能把门扉用途移植到每一件出土物。",
        "使用方式": "安装者将背部钉脚或铆榫穿入木板、棺板或器壁，再在正面穿置活动环。使用者握环拉门或使环撞击铺首发声，力量由兽面底座分散到承载面；若实例仅存兽面而无磨痕，原环的尺寸和动作幅度不宜补定。",
        "礼仪与制度": "铺首可进入宫室、宅门、墓门和葬具装饰，昂贵材质与复杂纹样往往对应较高制作成本。后世建筑制度对门饰形成等级差别，但先秦、秦汉实例的身份仍须结合建筑基址、墓葬规格和共出铭文，不能依据兽面威严直接判作皇家专用。",
        "史料记载": "国家博物馆的鎏金银铜铺首著录展示了兽面、衔环和背部固定关系；故宫名物资料将铺首解释为门上衔环的底座。馆藏实例同时说明，铺首也可脱离完整门扉保存，因此著录中的“铺首”不自动证明原建筑类型。",
        "器物组合": "完整门面通常由铺首、活动门环、门钉、木门板和轴枢共同工作：铺首固定承环，门环供握持或叩击，门钉另行加固门板。若兽面件与棺椁构件同出，则应转向葬具组合解释，避免仅凭外形复原成建筑大门。"
