        "形制与工艺": "铜门环可铸成圆环、扁环或带棱环，接口经合范铸接、焊合或套入环钮后封闭。受力处常见截面加厚和磨耗，表面也可鎏金或饰纹。环的直径、粗细与悬挂方式随门体而变，单件不能推定整座门的尺度。",
        "用途": "门环兼有把手和叩门件两种常见作用：向外牵拉可以启闭门扉，摆动环体撞击环座或门板则能传声。某些墓门、棺椁或礼仪陈设上的环未必承担频繁启闭，实际用途应由磨痕、轴孔和所在构件判断。",
        "使用方式": "使用者抓住环体下缘，沿门扇开启方向施力；需要通报时，可抬起后放下，使环与金属座或门面接触。环钮承担持续剪切，铺首扩大受力面积。遗物若只存孤环，不能凭圆形外观确定它原来挂在门上还是器物上。",
        "礼仪与制度": "门环的材质、尺寸和装饰可参与建筑立面秩序，但其基本功能是启闭门扉。北京古代建筑博物馆以明清门钹说明环件与门饰的结合；其中形成于后世的式样和等级安排，不能无条件倒推到商周或秦汉建筑。",
        "史料记载": "国家博物馆铺首实物保留衔环关系，为活动环如何挂在固定座上提供直观证据；北京古代建筑博物馆又说明，明清门钹中部凸出并连接扣门铁环。两项材料都不能支持把任何出土铜环直接定作门环。",
        "器物组合": "门环必须依赖环钮、铺首或门板上的穿接构件才能工作，并与门轴、插闩共同完成启闭。它不同于门钉的固定钉帽，也不同于容器耳部的提梁环；原位、磨损方向和承载对象，是区分这些圆环件的关键。"
