        "总介绍": "门钉由露在门外的隆起钉帽和进入门板的钉体组成，是固定不动的门扉构件。它既能连接厚木板、压住包覆层，也能以成行钉帽组织门面。与门环相比，门钉不供手握；与一般装饰圆片相比，它应有穿入或铆固结构。",
        "形制与工艺": "钉帽常作圆饼、半球或泡形，钉体则为直杆、方杆或可在背面弯折的铆脚。铜件可整铸，也可将帽、杆分别制作后结合。旧门上残留的孔径、背面铆痕和钉帽间距，比正面颜色更能识别原装方式。",
        "用途": "门钉把多层门板、横带或金属包皮压合在一起，分散局部应力，减少板材翘动；整齐排列又形成稳定的视觉节奏。部分晚期实例装饰性强于结构作用，但没有钉体或原门证据时，仍不宜把散见圆泡一概解释为门钉。",
        "使用方式": "制作门扇时先按横带和板缝定位钻孔，再从外侧插入钉体，内侧通过弯折、铆压或配合背板锁紧。外露钉帽承受触碰和风化，却不随启闭转动。修缮中若更换钉位，应以原孔和旧痕为依据，不能只追求等距排布。",
        "礼仪与制度": "门钉后来成为宫殿、坛庙和宅门立面中的显著等级符号，数量、材质和排列受建筑制度影响。此类规则有明确时代边界；面对早期遗址或孤立铜钉，只能先讨论装配技术，不能套用明清门制来判定建筑主人。",
        "史料记载": "北京市地方标准把门钉列入古建筑木结构维护内容，并以钉帽、钉杆和门板的实际状态规定修缮方法。该资料可证明传统门钉的构造与安装逻辑，却不是先秦器物的断代依据，早期实例仍需考古层位支持。",
        "器物组合": "门钉通常与门板横带、包铁或包铜层共同受力，铺首和门环则占据便于操作的位置。若一批钉帽保持规则行列并与木门遗迹相连，可讨论整扇门的结构；散落于棺椁或车舆附近时，还要排查其他铆钉用途。"
