      "slug": "yue-weapon",
      "nameZh": "钺",
      "copy": {
        "总介绍": "钺是刃部宽展、常呈弧形的大型劈砍器，既见实用兵器，也常作为权力和仪仗象征。铜钺以刃、身、肩和装柄部构成，部分器身透雕或铸兽面。它与斧接近，区分需结合刃宽、弧度、体量和出土语境。",
        "形制与工艺": "钺身多为扁平宽板，下缘或外缘开出弧刃，上部以銎、内或穿孔接木柄；器肩可设凸齿，板面可透雕、铸纹或铭文。宽刃铸件需兼顾薄厚和强度，成器后修磨刃口，礼仪件则可能保留厚钝边缘。",
        "用途": "实用钺依靠器头重量和宽刃产生强力劈砍，也可用于处决等威慑场景；礼仪钺则在仪仗、祭祀或随葬中显示武权。是否真正用于砍击，应检查刃部磨损、缺口和柄部受力，不能仅凭器名决定。",
        "使用方式": "木柄装入銎腔或贴合器内，再用销钉、绑缚固定，操作者握柄举起后向目标下劈。宽刃使冲击集中在弧缘，器头越重越需要稳定双手控制。若器身轻薄、透雕且未开锋，更适合解释为陈设或仪仗。",
        "礼仪与制度": "商周铜钺频繁出现在高等级墓葬和礼仪图像中，可与军事指挥、刑威和身份象征相连。妇好墓等具体组合能支持器主语境，但不能把所有钺都称为王权专属；地方首领、仪仗和实战装备之间仍有差别。",
        "史料记载": "故宫铜钺条目与国家博物馆兽面纹、妇好墓钺实例，分别提供宽弧刃、装柄孔、纹饰和墓葬背景。馆方说明可支持劈砍与礼仪双重面向，却不提供一条适用于所有年代的斧钺尺寸分界。",
        "器物组合": "钺头须与坚固木柄和固定销缚配成整器，礼仪环境中还可能与戈、矛、盾及车马器成组。与斧比较时，要同时看刃宽、器重、装柄和共出物；与刀相比，钺的刃部横向展开，动作重心也更靠前。"
      },
