      "copy": {
        "总介绍": "铜刀以单侧开刃、另一侧留背为基本特征，可分短柄工具、随身短兵和装长柄的兵器。它与双刃剑的受力方式不同，功能范围也更宽。器名只能说明单刃结构，切肉小刀、手工业削具和军用大刀还须依据长度、重心、柄制与刃痕分别判断。",
        "形制与工艺": "刀身可直可弯，刃缘在一侧，背部加厚，前端形成尖或圆首；后部见短柄、扁茎、环首或銎口。青铜刀经铸造后修磨单刃，柄外还可包木、骨或缠绳。长度、重心与装柄方式决定它适合精细切削还是强力挥砍。",
        "用途": "短刀能切割肉食、皮革和植物，也可参与手工业；刃长、柄稳且重心前置的刀更适合作为近战或长柄劈砍兵器。随葬刀还可能表示职业和身份。用途判断要结合刃痕、尺寸、握柄及共出工具。",
        "使用方式": "短柄刀由手掌包握刀柄，刃缘沿材料表面切、削或割；长柄刀则借双手和器头惯性挥劈。单刃结构使刀背可承受不同方向的压力。柄已朽失时，应从茎、銎和铆孔判断握持长度，不能统一画成佩刀。",
        "礼仪与制度": "刀既属于生产和饮食工具，也进入军队、仪仗与墓葬。环首刀等形制在特定时期具有军事和身份含义，但早期铜刀不自动承接后世制度。装饰精细、铭文或成套武备可加强礼仪解释，单件小刀则要保留日常可能。",
        "史料记载": "国家博物馆商代铜刀条目展示单刃、弧背和短柄实例，馆藏秦兵器材料又说明刀类在军用环境中的形态差异。两组实物共同表明“刀”跨越工具与兵器，不能依据一个时代的长刀定义覆盖全部铜刀。",
        "器物组合": "短刀可与砺石、骨角料、食器或皮革工具同出，军用刀则可能配鞘、带具、盾和其他武器。剑鞘相似并不足以混称，关键仍是单刃与双刃；带銎长刀还需寻找木柲，避免按短柄佩刀复原。"
      },
