      "nameZh": "镞",
      "copy": {
        "总介绍": "镞是安装在箭杆前端的金属箭头，借弓或弩储存的能量高速飞行。铜镞有双翼、三棱、四棱、扁叶和近矛形等多种截面，以铤或骹连接箭杆。体量虽小，它与手持矛头在装柄尺度和成组数量上不同。",
        "形制与工艺": "镞由锋尖、刃翼或棱脊、关部及铤或骹组成。铤式插入箭杆，骹式套住杆端，部分再以缠线和胶固定。多棱截面提高穿透稳定性，宽翼形成较大创口；钝头、无刃或特殊孔槽则可能对应礼仪和信号用途。",
        "用途": "尖锐镞用于战争或狩猎，依飞行速度穿刺目标；宽翼、棱数与重量会影响穿透、创口和弹道。秦始皇帝陵一组四枚钝头镞被解释为仪仗箭，旁出的五十枚锐利四棱镞更接近实用弩矢，显示用途不可一概而论。",
        "使用方式": "制箭者把铤插入削出的箭杆孔，或将骹套在杆端，再用胶和缠线校正同轴；箭尾配羽以稳定飞行。射手将成箭搭在弓弦或弩槽上发射。孤镞若失去杆、羽和发射器，不能仅凭形态确定由弓还是弩使用。",
        "礼仪与制度": "大批规格接近的镞可反映武库生产、军需计量和弹药配发，特殊钝头组合则可能服务仪仗。秦陵兵器群提供了标准化与礼仪并存的实例，但单个宝鸡铜镞若无批次、铭文或原位，不能直接套入秦军编制。",
        "史料记载": "秦始皇帝陵博物院公布四枚钝头铜镞与五十枚锐利四棱镞的同坑差异；国家博物馆石镞条目说明镞底可用铤、扁薄部或凹口接入箭杆。两类资料支持发射与装配，不能据此给每件铜镞设定射程或杀伤数值。",
        "器物组合": "完整箭矢由镞、箭杆、缠线、胶合部和尾羽组成，再与弓、弩及箭箙形成使用系统。若与弩机和同规格箭杆成组，可加强弩矢判断；与狩猎动物遗存同出则另有语境。小型尖头也要排除锥、鱼镖等工具。"
      },
